<?php declare(strict_types=1);namespace App\Modules\SubcontractPayments\Controllers;use App\Core\Exceptions\BusinessRuleException;use App\Core\Exceptions\ValidationException;use App\Core\Http\Csrf;use App\Core\Http\Request;use App\Core\Http\Response;use App\Core\Http\Session;use App\Core\View\View;use App\Modules\AccessControl\Services\AuthorizationService;use App\Modules\SubcontractPayments\Services\SubcontractPaymentService;use App\Modules\SubcontractPayments\Validators\SubcontractPaymentValidator;final class SubcontractPaymentController{public function __construct(private readonly View$v,private readonly Csrf$csrf,private readonly Session$session,private readonly AuthorizationService$auth,private readonly SubcontractPaymentService$s,private readonly SubcontractPaymentValidator$validator){}public function index(Request$r):Response{$id=(int)$r->route('subcontract_id');$x=$this->s->subcontract($id);return Response::html($this->v->render('modules/subcontract-payments/index',['title'=>'دفعات مقاول الباطن','subcontract'=>$x,'summary'=>$this->s->financialSummary($id),'accounts'=>$this->s->paymentAccounts(),'canCreate'=>$this->auth->can('subcontract_payments.create')&&in_array($x['status'],['active','suspended','completed'],true)]));}public function create(Request$r):Response{return$this->form((int)$r->route('subcontract_id'),null);}public function edit(Request$r):Response{$p=$this->s->find((int)$r->route('id'));return$this->form((int)$p['subcontract_id'],(int)$p['id']);}public function show(Request$r):Response{$p=$this->s->find((int)$r->route('id'));return Response::html($this->v->render('modules/subcontract-payments/show',['title'=>'تفاصيل دفعة مقاول الباطن','payment'=>$p,'canEdit'=>$this->auth->can('subcontract_payments.edit'),'canPost'=>$this->auth->can('subcontract_payments.post'),'canCancel'=>$this->auth->can('subcontract_payments.cancel')]));}public function store(Request$r):Response{return$this->save($r,null,(int)$r->route('subcontract_id'));}public function update(Request$r):Response{$p=$this->s->find((int)$r->route('id'));return$this->save($r,(int)$p['id'],(int)$p['subcontract_id']);}public function post(Request$r):Response{return$this->action($r,'post');}public function cancel(Request$r):Response{return$this->action($r,'cancel');}private function form(int$s,?int$id):Response{$p=$id?$this->s->find($id):null;if($p&&$p['status']!=='draft')throw new BusinessRuleException('الدفعة غير قابلة للتعديل.');return Response::html($this->v->render('modules/subcontract-payments/form',['title'=>$id?'تعديل مسودة الدفعة':'إضافة دفعة','subcontract'=>$this->s->subcontract($s),'payment'=>$p,'summary'=>$this->s->financialSummary($s),'accounts'=>$this->s->paymentAccounts()]));}private function save(Request$r,?int$id,int$s):Response{if(!$this->csrf->isValid($r->input('_token')))return Response::html('انتهت صلاحية الطلب.',419);try{$id=$this->s->save($this->validator->validate($r->all(),$s),$id);$this->flash('success','تم الحفظ','تم حفظ مسودة الدفعة.');return Response::redirect('/subcontract-payments/'.$id);}catch(ValidationException|BusinessRuleException$e){$m=$e instanceof ValidationException?$this->validationMessage($e):$e->getMessage();$this->flash('error','تعذر الحفظ',$m);return Response::redirect($id?'/subcontract-payments/'.$id.'/edit':'/subcontracts/'.$s.'/payments');}}private function action(Request$r,string$a):Response{if(!$this->csrf->isValid($r->input('_token')))return Response::html('انتهت صلاحية الطلب.',419);$id=(int)$r->route('id');try{$a==='post'?$this->s->post($id):$this->s->cancel($id);$this->flash('success','تم التحديث',$a==='post'?'تم ترحيل الدفعة والقيد المحاسبي.':'تم إلغاء المسودة.');}catch(BusinessRuleException$e){$this->flash('error','تعذر التحديث',$e->getMessage());}return Response::redirect('/subcontract-payments/'.$id);}private function validationMessage(ValidationException$e):string{$errors=$e->errors;$key=array_key_first($errors);return(string)(($key!==null?($errors[$key][0]??null):null)??'يرجى مراجعة البيانات.');}private function flash(string$t,string$h,string$x):void{$this->session->flash('alert',['type'=>$t,'title'=>$h,'text'=>$x]);}}
